class TreeNode:
    def __init__(self, val, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right


def build_tree(arr):
    if not arr or arr[0] is None:
        return None
    root = TreeNode(arr[0])
    queue = [root]
    i = 1
    while i < len(arr) and queue:
        node = queue.pop(0)
        if i < len(arr):
            left_val = arr[i]
            i += 1
            if left_val is not None:
                node.left = TreeNode(left_val)
                queue.append(node.left)
        if i < len(arr):
            right_val = arr[i]
            i += 1
            if right_val is not None:
                node.right = TreeNode(right_val)
                queue.append(node.right)
    return root


def leaf_similar(root1_arr, root2_arr):
    root1 = build_tree(root1_arr)
    root2 = build_tree(root2_arr)

    def leaves(node, acc):
        if node is None:
            return
        if node.left is None and node.right is None:
            acc.append(node.val)
            return
        leaves(node.left, acc)
        leaves(node.right, acc)

    seq1, seq2 = [], []
    leaves(root1, seq1)
    leaves(root2, seq2)
    return seq1 == seq2

